import{_ as a}from"./chunks/setup.Bt8oi71S.js";import{_ as r,o as s,c as o,a2 as e}from"./chunks/framework.DSc8fo6x.js";const _=JSON.parse('{"title":"Установка и первый запуск","description":"","frontmatter":{},"headers":[],"relativePath":"ru/qurasdirma.md","filePath":"ru/qurasdirma.md"}'),l={name:"ru/qurasdirma.md"};function n(i,t,d,h,g,m){return s(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="установка-и-первыи-запуск" tabindex="-1">Установка и первый запуск <a class="header-anchor" href="#установка-и-первыи-запуск" aria-label="Permalink to &quot;Установка и первый запуск&quot;">​</a></h1><p>Эта страница — для того, кто устанавливает программу (обычно владелец магазина). Делается один раз.</p><h2 id="_1-скачать-программу" tabindex="-1">1. Скачать программу <a class="header-anchor" href="#_1-скачать-программу" aria-label="Permalink to &quot;1. Скачать программу&quot;">​</a></h2><p>Последняя версия: <strong><a href="https://github.com/Camalzadeh/kassa-releases/releases/latest" target="_blank" rel="noreferrer">Kassa-Setup — скачать</a></strong> (файл <code>Kassa-Setup-….exe</code>).</p><h2 id="_2-установить" tabindex="-1">2. Установить <a class="header-anchor" href="#_2-установить" aria-label="Permalink to &quot;2. Установить&quot;">​</a></h2><ol><li>Откройте файл <code>Kassa-Setup-….exe</code>.</li><li>Если Windows пишет «неизвестная программа»: <strong>«Подробнее» → «Выполнить в любом случае»</strong>.</li><li>Выберите язык (Azərbaycanca, Русский, English).</li><li>Выберите вариант установки: <ul><li><strong>«Установить для всех пользователей» (рекомендуется для магазина)</strong> — Windows спросит пароль администратора. Программа работает в защищённом режиме: кассир не может удалить программу и данные. См. <a href="#windows">Учётные записи Windows</a>.</li><li><strong>«Установить только для меня»</strong> — пароль администратора не нужен. Для пробы или домашнего компьютера.</li></ul></li><li><strong>Далее → Установить → Завершить</strong>. На рабочем столе появится зелёный значок <strong>Kassa</strong>.</li></ol><h2 id="_3-первыи-запуск" tabindex="-1">3. Первый запуск <a class="header-anchor" href="#_3-первыи-запуск" aria-label="Permalink to &quot;3. Первый запуск&quot;">​</a></h2><p><img src="'+a+'" alt="Первоначальная настройка"></p><ol><li><strong>Пароль установки</strong> — получите его у того, кто дал вам программу. Спрашивается только в первый раз.</li><li>Выберите язык, введите <strong>название магазина</strong>, <strong>своё имя</strong> и <strong>пароль</strong> (не менее 8 символов, буквы и цифры). Вы становитесь <strong>админом</strong> магазина.</li><li><strong>Установить</strong>.</li></ol><h2 id="_4-код-восстановления-—-обязательно-запишите-на-бумаге" tabindex="-1">4. Код восстановления — обязательно запишите на бумаге <a class="header-anchor" href="#_4-код-восстановления-—-обязательно-запишите-на-бумаге" aria-label="Permalink to &quot;4. Код восстановления — обязательно запишите на бумаге&quot;">​</a></h2><p>После установки на экране появится <strong>код восстановления</strong>.</p><ul><li><strong>Запишите его на бумаге</strong> и храните дома или в сейфе. Не храните его файлом на компьютере.</li><li>Если компьютер сломается или его украдут, вернуть данные можно <strong>только с этим кодом</strong>.</li><li>Посмотреть его можно и позже: <strong>Бэкап → Код восстановления</strong> → ваш пароль.</li></ul><p>Поставьте галочку <strong>«Я записал код…»</strong> → <strong>Продолжить</strong>.</p><h2 id="windows" tabindex="-1">5. Учётные записи Windows: отдельная запись для кассира <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;5. Учётные записи Windows: отдельная запись для кассира {#windows}&quot;">​</a></h2><p>Самая надёжная защита (при установке «Для всех пользователей»):</p><ol><li>Для <strong>владельца</strong> — учётная запись Windows <strong>администратора с паролем</strong>. С неё Kassa устанавливают и обновляют.</li><li>Для <strong>кассира</strong> — <strong>стандартная</strong> учётная запись (не администратор): Параметры → Учётные записи → Другие пользователи → <strong>Добавить учётную запись</strong> → тип учётной записи <strong>«Стандартный пользователь»</strong>.</li><li>Каждый день компьютер работает <strong>под учётной записью кассира</strong>. Kassa работает и там, но кассир не может удалить или изменить программу и файлы данных.</li><li>В Kassa каждый входит под своим <strong>именем и паролем Kassa</strong> (они не связаны с паролем Windows).</li></ol><p>В этом режиме закрытие окна не останавливает программу полностью — она работает в фоне (отчёт в Telegram, бэкап). Это нормально.</p><h2 id="_6-что-делать-дальше" tabindex="-1">6. Что делать дальше <a class="header-anchor" href="#_6-что-делать-дальше" aria-label="Permalink to &quot;6. Что делать дальше&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Шаг</th><th>Где</th></tr></thead><tbody><tr><td>Данные магазина (адрес, телефон, ИНН (VÖEN) — видны в чеке)</td><td><a href="./ayarlar.html">Настройки</a></td></tr><tr><td>Учётная запись кассира</td><td><a href="./istifadeciler.html">Пользователи</a></td></tr><tr><td>Ввести товары</td><td><a href="./mallar.html">Товары</a>, <a href="./mal-qebulu.html">Приёмка товара</a></td></tr><tr><td>Принтер чеков и этикеток</td><td><a href="./printerler.html">Принтер</a></td></tr><tr><td>Ежедневный отчёт и бэкап на телефон</td><td><a href="./telegram.html">Telegram</a></td></tr><tr><td>Еженедельный бэкап на USB</td><td><a href="./backup.html">Бэкап</a></td></tr></tbody></table>',19)])])}const p=r(l,[["render",n]]);export{_ as __pageData,p as default};
